// Copies the wire types generated by orbyn-engine into src/generated/.
import { copyFileSync, existsSync, mkdirSync, readdirSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const engine = resolve(
  process.env.ORBYN_ENGINE_DIR ?? join(root, "../../../orbyn-engine-wt/foundation"),
);
const from = join(engine, "crates/orbyn-contracts/bindings");
const to = join(root, "src/generated");

if (!existsSync(from)) {
  console.error(
    `generate: no bindings at ${from}\nSet ORBYN_ENGINE_DIR to an orbyn-engine checkout that has built its contracts.`,
  );
  process.exit(1);
}
const files = readdirSync(from).filter((f) => f.endsWith(".ts"));
if (files.length === 0) {
  console.error(`generate: no .ts files in ${from}`);
  process.exit(1);
}
mkdirSync(to, { recursive: true });
for (const f of files) copyFileSync(join(from, f), join(to, f));
console.log(`generate: copied ${files.length} file(s) from ${from}`);
